document.addEventListener('submit',async e=>{if(e.target.id!=='metadata-form')return;e.preventDefault();const t=getTrack(e.target.dataset.track),data=new FormData(e.target);const title=String(data.get('title')).trim(),artist=String(data.get('artist')).trim();if(!title||!artist)return;const updated={...t,title,artist,album:String(data.get('album')).trim()||'On your device'};try{await dbRequest('readwrite',store=>store.put({...updated,src:undefined}));Object.assign(t,updated);lyricCache.delete(t.id);sheet.close();render();updatePlayer();if(now.open)loadLyrics(t,true);toast('Song details saved')}catch{toast('Song details could not be saved.')}});

const releases=new Map();
let releaseController=null,releaseTimer=null,releaseEpoch=0,selectedRelease=null,releaseRegion=read('release-region','us');
function cancelReleaseSearch(){clearTimeout(releaseTimer);releaseController?.abort();releaseEpoch++}
function scheduleReleaseSearch(wait=350){cancelReleaseSearch();const area=$('#search-results');if(!area)return;area.innerHTML=`<div class="release-region"><label for="release-region">Catalog region</label><select id="release-region"><option value="us">United States</option><option value="kr">South Korea</option><option value="jp">Japan</option><option value="gb">United Kingdom</option><option value="tw">Taiwan</option></select></div><div id="release-results"></div>`;$('#release-region').value=releaseRegion;if(!query.trim()){$('#release-results').innerHTML=empty('Find the music you love.','Search a K-pop artist, a song title, or an album. Release details come from Apple’s catalog. Use your own audio file for full playback here.');return}$('#release-results').innerHTML='<div class="catalog-loading" role="status">Searching official releases…</div>';releaseTimer=setTimeout(fetchReleases,wait)}
async function fetchReleases(){const epoch=releaseEpoch;releaseController=new AbortController();const controller=releaseController,timeout=setTimeout(()=>controller.abort(),12000);const url=new URL('https://itunes.apple.com/search');for(const[k,v]of Object.entries({term:query.trim(),entity:'song',media:'music',limit:50,country:releaseRegion}))url.searchParams.set(k,v);try{const response=await fetch(url,{signal:controller.signal,credentials:'omit'});if(!response.ok)throw new Error('The release catalog is temporarily unavailable. Please try again.');const data=await response.json();if(epoch!==releaseEpoch||view!=='search'||searchSource!=='catalog')return;const result=(data.results||[]).filter(t=>t.kind==='song'&&t.trackId).map(t=>({id:'apple-'+t.trackId,title:t.trackName,artist:t.artistName,album:t.collectionName||'',duration:t.trackTimeMillis/1000,cover:safeArtwork(t.artworkUrl100?.replace('100x100bb','600x600bb')),mood:t.primaryGenreName||'',url:t.trackViewUrl,region:releaseRegion}));result.forEach(t=>releases.set(t.id,t));$('#release-results').innerHTML=`<div class="section-heading"><div><h2>Official releases</h2><p>${result.length} results · Details and links from Apple</p></div></div>${result.length?`<div class="release-list">${result.map(t=>`<button class="release-row" data-release="${esc(t.id)}" aria-label="View ${esc(t.title)} by ${esc(t.artist)}"><img src="${esc(t.cover)}" alt=""><span><strong>${esc(t.title)}</strong><small>${esc(t.artist)} · ${esc(t.album)}</small></span><span class="release-time">${format(t.duration)}</span>${icon('arrow')}</button>`).join('')}</div>`:empty('Try another title or region.','No releases matched this search in the selected catalog.')}`}catch(error){if(epoch!==releaseEpoch)return;const area=$('#release-results');if(area)area.innerHTML=empty('The catalog will be back.',error.name==='AbortError'?'The search took too long. Try again.':error.message,'<button class="primary-btn" id="retry-releases">Try again</button>')}finally{clearTimeout(timeout)}}
function showRelease(id){const t=releases.get(id);if(!t)return;openSheet('OFFICIAL RELEASE',`<img class="sheet-cover release-cover" src="${esc(t.cover)}" alt="${esc(t.album)}"><h2>${esc(t.title)}</h2><p>${esc(t.artist)}<br>${esc(t.album)} · ${format(t.duration)}</p><p>Play this release in Echo using your own audio file. Artwork and song details will be attached to the file, and matching lyrics will be looked up automatically.</p><div class="action-menu"><button data-import-release="${esc(t.id)}">${icon('upload')} Import my audio file</button><button data-choose-release="${esc(t.id)}">${icon('library')} Choose a file from my library</button></div><a class="apple-music-link" href="${esc(t.url)}" target="_blank" rel="noopener">Listen on Apple Music ${icon('arrow')}</a><p class="release-fineprint">Apple Music playback is subject to its subscription and regional availability. Echo does not include a commercial streaming subscription.</p>`)}
function chooseReleaseFile(id){const t=releases.get(id);if(!t)return;const imported=tracks.filter(t=>t.local);openSheet('YOUR MUSIC, MATCHED',`<h2>Choose your recording.</h2><p>Match your copy of ${esc(t.title)} to its official details.</p>${imported.length?imported.map(file=>`<div class="sheet-track"><img src="${esc(file.cover)}" alt=""><button class="sheet-track-info" data-attach-release="${esc(file.id)}" data-release-id="${esc(id)}"><strong>${esc(file.title)}</strong><small>${esc(file.artist)} · ${format(file.duration)}</small></button></div>`).join(''):'<p>Import an audio file first to add it to your library.</p>'}<div class="form-row"><button class="primary-btn" data-import-release="${esc(id)}">Import my audio file</button></div>`)}
async function attachReleaseFile(id,releaseId){const t=getTrack(id),release=releases.get(releaseId);if(!t?.local||!release)return;const updated={...t,title:release.title,artist:release.artist,album:release.album,cover:release.cover,mood:release.mood};try{await dbRequest('readwrite',store=>store.put({...updated,src:undefined}));Object.assign(t,updated);lyricCache.delete(id);sheet.close();playTrack(id,[id]);openNowPlaying();loadLyrics(t,true);if(view==='library')render()}catch{toast('The file could not be updated.')}}
document.addEventListener('change',e=>{if(e.target.id==='release-region'){releaseRegion=e.target.value;save('release-region',releaseRegion);scheduleReleaseSearch(0)}});
document.addEventListener('click',e=>{if(e.target.closest('#retry-releases'))scheduleReleaseSearch(0)});

const youtubeFeatured=[
 {videoId:'c6ASQOwKkhk',title:'The Astronaut',artist:'Jin'},
 {videoId:'gdZLi9oWNZg',title:'Dynamite',artist:'BTS'},
 {videoId:'gQlMMD8auMs',title:'Pink Venom',artist:'BLACKPINK'},
 {videoId:'i0p1bmr0EmE',title:'What is Love?',artist:'TWICE'}
];
let youtubeResults=[],youtubeTimer=null,youtubeController=null,youtubeEpoch=0,youtubeContinuation=null,youtubeFilter='songs',youtubeLoading=false;
function youtubeTrack(video){return {id:'youtube-'+video.videoId,videoId:video.videoId,title:video.title||'YouTube 视频 '+video.videoId,artist:video.artist||'YouTube',album:video.album||'YouTube Music',mood:'YouTube',duration:Number(video.duration)||0,cover:video.cover?safeArtwork(video.cover):'https://i.ytimg.com/vi/'+video.videoId+'/hqdefault.jpg',src:'youtube:'+video.videoId,provider:'youtube',remote:true,permalink:'https://www.youtube.com/watch?v='+video.videoId}}
function videoCard(video){return `<button class="video-card" data-video="${video.videoId}"><div><img src="https://i.ytimg.com/vi/${video.videoId}/hqdefault.jpg" alt="${esc(video.title)}" loading="lazy"><span>${icon('play')}</span></div><strong>${esc(video.title)}</strong><small>${esc(video.artist)} · YouTube</small></button>`}
function parseYouTubeURL(value){try{const url=new URL(value.trim());if(!['https:','http:'].includes(url.protocol))return null;const host=url.hostname.toLowerCase().replace(/^www\./,'');let id=null;if(host==='youtu.be')id=url.pathname.split('/')[1];else if(['youtube.com','m.youtube.com','music.youtube.com','youtube-nocookie.com'].includes(host)){id=url.searchParams.get('v');if(!id&&/^\/(shorts|embed|live)\//.test(url.pathname))id=url.pathname.split('/')[2]}return /^[A-Za-z0-9_-]{11}$/.test(id||'')?id:null}catch{return null}}
function playYouTube(videoId,video=null){if(!/^[A-Za-z0-9_-]{11}$/.test(videoId))return;const id='youtube-'+videoId;if(!getTrack(id)){const item=youtubeFeatured.find(t=>t.videoId===videoId)||video||{videoId};tracks.push(youtubeTrack(item))}playTrack(id,youtubeResults.some(t=>t.id===id)?youtubeResults.map(t=>t.id):youtubeFeatured.some(t=>t.videoId===videoId)?youtubeFeatured.map(t=>'youtube-'+t.videoId):[id]);rememberOnline();placeYouTube()}
function youtubeForm(initial=''){openSheet('YOUTUBE',`<h2>添加 YouTube</h2><form id="youtube-form"><label class="form-field">视频或 YouTube Music 链接<input type="url" name="url" required value="${esc(initial)}" inputmode="url"></label><label class="form-field">歌曲名（可选）<input name="title" maxlength="180"></label><label class="form-field">歌手（可选）<input name="artist" maxlength="180"></label><button class="primary-btn" type="submit">${icon('play')} 播放</button><p class="form-message" role="status"></p></form>`)}
function cancelYouTubeSearch(){clearTimeout(youtubeTimer);youtubeController?.abort();youtubeEpoch++;youtubeLoading=false}
function scheduleYouTubeSearch(wait=350){cancelYouTubeSearch();youtubeResults=[];youtubeContinuation=null;const area=$('#search-results');if(!area)return;const clear=$('#clear-search');if(clear)clear.hidden=!query;const term=query.trim(),videoId=parseYouTubeURL(term);if(videoId){youtubeResults=[youtubeTrack({videoId})];youtubeResults.forEach(t=>{if(!getTrack(t.id))tracks.push(t)});renderYouTubeResults();return}if(!term){area.innerHTML=`<div class="section-heading"><h2>听点什么</h2></div><div class="video-grid">${youtubeFeatured.map(videoCard).join('')}</div>`;return}if(!window.ECHO_CONFIG?.supabaseUrl&&!window.ECHO_CONFIG?.youtubeApiKey){area.innerHTML=empty('搜索服务未连接','连接音乐搜索后端后即可在这里搜歌。','<button class="secondary-btn" id="youtube-search-retry">重试</button>');return}area.innerHTML='<div class="catalog-loading" role="status">正在搜索 YouTube Music…</div>';youtubeTimer=setTimeout(()=>fetchYouTubeSearch(),wait)}
function decodeTitle(value){const text=document.createElement('textarea');text.innerHTML=value;return text.value}
async function fetchYouTubeSearch(append=false){if(youtubeLoading||view!=='search'||searchSource!=='youtube')return;youtubeLoading=true;const epoch=youtubeEpoch,term=query.trim();youtubeController=new AbortController();const controller=youtubeController,timeout=setTimeout(()=>controller.abort(),18000);const more=$('#youtube-more');if(append&&more){more.disabled=true;more.textContent='正在加载…'}try{const config=window.ECHO_CONFIG||{};let response,result;if(config.supabaseUrl&&config.supabaseAnonKey){response=await fetch(config.supabaseUrl+'/functions/v1/youtube-search',{method:'POST',signal:controller.signal,credentials:'omit',headers:{'Content-Type':'application/json',apikey:config.supabaseAnonKey},body:JSON.stringify({q:term,filter:youtubeFilter,...(append&&youtubeContinuation?{continuation:youtubeContinuation}:{})})});result=await response.json()}else{const url=new URL('https://www.googleapis.com/youtube/v3/search');for(const[key,value]of Object.entries({key:config.youtubeApiKey,part:'snippet',q:term,type:'video',videoCategoryId:'10',videoEmbeddable:'true',maxResults:'20',safeSearch:'moderate',...(append&&youtubeContinuation?{pageToken:youtubeContinuation}:{})}))url.searchParams.set(key,value);response=await fetch(url,{signal:controller.signal,credentials:'omit'});result=await response.json();if(response.ok)result={items:(result.items||[]).map(x=>({videoId:x.id?.videoId,title:decodeTitle(x.snippet?.title||''),artist:decodeTitle(x.snippet?.channelTitle||'')})),continuation:result.nextPageToken||null}}if(epoch!==youtubeEpoch||view!=='search'||searchSource!=='youtube')return;if(!response.ok)throw new Error(response.status===429?'搜索次数较多，请稍后重试。':response.status===504?'搜索超时，请重试。':'暂时无法连接音乐搜索，请重试。');if(!Array.isArray(result.items))throw new Error('搜索响应异常，请重试。');const found=result.items.filter(x=>/^[A-Za-z0-9_-]{11}$/.test(x.videoId)).map(youtubeTrack);youtubeResults=[...new Map((append?[...youtubeResults,...found]:found).map(t=>[t.id,t])).values()];youtubeContinuation=result.continuation||null;for(const track of youtubeResults){const existing=getTrack(track.id);if(existing)Object.assign(existing,track);else tracks.push(track)}renderYouTubeResults()}catch(error){if(epoch===youtubeEpoch&&view==='search'&&searchSource==='youtube'){const message=error.name==='AbortError'?'搜索超时，请重试。':error.message;if(append){toast(message);if(more?.isConnected){more.disabled=false;more.textContent='加载更多'}}else{const area=$('#search-results');if(area)area.innerHTML=empty('暂时无法搜索',message,'<button class="primary-btn" id="youtube-search-retry">重试</button>')}}}finally{clearTimeout(timeout);if(epoch===youtubeEpoch)youtubeLoading=false}}
function renderYouTubeResults(){const area=$('#search-results');if(!area)return;area.innerHTML=`<div class="search-filters" role="group" aria-label="结果类型">${[['songs','歌曲'],['videos','视频']].map(([key,label])=>`<button data-youtube-filter="${key}" aria-pressed="${youtubeFilter===key}" class="${youtubeFilter===key?'active':''}">${label}</button>`).join('')}</div><div class="search-heading"><h2>${query.trim()?'搜索结果':'YouTube Music'}</h2><span>${youtubeResults.length} 首</span></div>${youtubeResults.length?trackRows(youtubeResults):empty('没有找到结果','试试其他歌曲名或歌手。')}${youtubeContinuation?'<div class="catalog-more"><button class="secondary-btn" id="youtube-more">加载更多</button></div>':''}`}
function placeYouTube(){const dock=$('#youtube-dock');if(audio.provider!=='youtube'){dock.hidden=true;return}dock.hidden=false;dock.dataset.expanded=String(now.open);if(now.open){const rect=$('#np-video-slot').getBoundingClientRect();dock.style.position='fixed';dock.style.left=rect.left+'px';dock.style.top=rect.top+'px';dock.style.width=Math.max(200,rect.width)+'px';dock.style.right='auto';dock.style.bottom='auto'}else{for(const key of ['position','left','top','width','right','bottom'])dock.style.removeProperty(key)}}
function reconcilePlayerMode(){if(!now.open)return;const desired=audio.provider==='youtube'?'youtube':'audio';if(now.dataset.mode!==desired){now.close();now.dataset.mode=desired;if(desired==='youtube')now.show();else now.showModal()}document.body.classList.add('now-open');if(desired==='youtube'){for(const selector of ['.sidebar','.workspace','.player','.bottom-nav'])$(selector).inert=true}placeYouTube()}
audio.addEventListener('gestureblocked',()=>toast('请点击视频中的播放按钮。'));
audio.addEventListener('sourcechange',()=>{reconcilePlayerMode();placeYouTube()});
audio.addEventListener('videometadata',event=>{const track=getTrack('youtube-'+event.detail.videoId);if(!track)return;const title=track.title.startsWith('YouTube 视频 ')?event.detail.title:track.title,artist=track.artist==='YouTube'?event.detail.artist:track.artist,changed=track.title!==title||track.artist!==artist||(event.detail.duration>0&&Math.abs((track.duration||0)-event.detail.duration)>1);Object.assign(track,{title,artist,uploader:event.detail.artist,duration:Number(event.detail.duration)||track.duration});if(changed){updatePlayer();rememberOnline()}});
now.addEventListener('close',()=>{if(now.open)return;now.removeAttribute('aria-modal');document.body.classList.remove('now-open');for(const selector of ['.sidebar','.workspace','.player','.bottom-nav'])$(selector).inert=false;placeYouTube();if(nowTrigger?.isConnected)nowTrigger.focus({preventScroll:true})});
window.addEventListener('resize',()=>{if(audio.provider==='youtube')placeYouTube()});
window.visualViewport?.addEventListener('resize',placeYouTube);
now.addEventListener('scroll',()=>{if(audio.provider==='youtube')placeYouTube()},{passive:true});
if(typeof ResizeObserver==='function')new ResizeObserver(()=>{if(audio.provider==='youtube'&&now.open)placeYouTube()}).observe($('#np-video-slot'));
document.addEventListener('keydown',e=>{if(!now.open||sheet.open)return;if(e.key==='Escape'&&now.dataset.mode==='youtube')now.close();if(e.key==='Tab'&&now.dataset.mode==='youtube'){const nodes=$$('button:not([disabled]),input:not([disabled]),a[href],iframe,[tabindex="0"]',now).concat($$('a[href],button:not([disabled]),iframe',$('#youtube-dock'))).filter(el=>{for(let node=el;node&&node!==document;node=node.parentElement){if(node.hidden||getComputedStyle(node).display==='none'||getComputedStyle(node).visibility==='hidden')return false}return true});const first=nodes[0],last=nodes.at(-1);if(!first)return;if(e.shiftKey&&(document.activeElement===first||!nodes.includes(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!nodes.includes(document.activeElement))){e.preventDefault();first.focus()}}});
document.addEventListener('submit',e=>{if(e.target.id==='youtube-form'){e.preventDefault();const form=e.target,data=new FormData(form),id=parseYouTubeURL(String(data.get('url')));if(!id){$('.form-message',form).textContent='请输入有效的 YouTube 视频链接。';return}const item=youtubeTrack({videoId:id,title:String(data.get('title')||'').trim(),artist:String(data.get('artist')||'').trim()});const existing=getTrack(item.id);if(!existing)tracks.push(item);sheet.close();playYouTube(id,item)}if(e.target.id==='music-search-form'){e.preventDefault();if(searchSource==='youtube')scheduleYouTubeSearch(0)}if(e.target.id==='home-search-form'){e.preventDefault();const term=$('#home-query').value.trim();if(!term)return;searchSource='youtube';setView('search');query=term;$('#music-search').value=term;renderResults()}});
for(const video of youtubeFeatured)if(!getTrack('youtube-'+video.videoId))tracks.push(youtubeTrack(video));

const cloud=new EchoAccountService(window.ECHO_CONFIG||{}),sharedCollections=new Map();
const deletedAccountIds=new Set();
let accountUid=undefined,accountEpoch=0,accountMode='signin',friendEpoch=0;
function portableTrack(t){const item={};for(const key of ['id','title','artist','album','duration','cover','provider','videoId','remote','instrumental','mood','permalink'])if(t[key]!==undefined)item[key]=t[key];if(t.local){item.local=true;item.deviceOnly=true}else if(t.src&&(/^(https:|youtube:)/.test(t.src)||bundled.some(b=>b.id===t.id)))item.src=t.src;return item}
function cacheSnapshot(){return {likes:[...liked],playlists:JSON.parse(JSON.stringify(playlists)),tracks:tracks.filter(t=>liked.has(t.id)||playlists.some(p=>p.ids.includes(t.id))).map(portableTrack)}}
function registerCloudTrack(value){if(bundled.some(t=>t.id===value?.id))return;if(!value?.id||typeof value.title!=='string')return;const t={...value,mood:value.mood||'',cover:safeArtwork(value.cover)};if(value.local){t.src=undefined;t.deviceOnly=true}else if(value.provider==='youtube'&&/^[A-Za-z0-9_-]{11}$/.test(value.videoId)){t.src='youtube:'+value.videoId}else if(value.id.startsWith('audius-')&&/^[A-Za-z0-9]+$/.test(value.id.slice(7))){t.src=CATALOG_API+'/tracks/'+value.id.slice(7)+'/stream?app_name=Echo'}else if(!bundled.some(b=>b.id===value.id)){if(!/^https:/.test(value.src||''))delete t.src}const existing=getTrack(t.id);if(existing?.file)return;if(existing)Object.assign(existing,t);else tracks.push(t)}
function cloudLike(id,state){if(!cloud.user)return;const t=getTrack(id);if(t)try{cloud.queue({type:'like',liked:state,track:portableTrack(t)})}catch{toast('同步暂不可用，本机收藏已保留。')}}
function cloudPlaylist(p){if(!cloud.user||!p)return;try{cloud.queue({type:'playlist',id:p.id,name:p.title,cover:p.cover,visibility:p.visibility||'private',tracks:p.ids.map(getTrack).filter(Boolean).map(portableTrack)})}catch{toast('同步暂不可用，本机歌单已保留。')}}
function cloudDeletePlaylist(id){if(!cloud.user)return;try{cloud.queue({type:'deletePlaylist',id})}catch{toast('删除暂未同步，请稍后重试。')}}
async function hydrateLibrary(){const uid=cloud.user?.id,epoch=accountEpoch;if(!uid)return;const data=await cloud.library();if(uid!==cloud.user?.id||epoch!==accountEpoch)return;const likeMap=new Map(data.likes.map(x=>[x.track_id,x.track])),listMap=new Map(data.playlists.map(p=>[p.id,{id:p.id,title:p.name,cover:p.cover||'assets/sea.jpg',visibility:p.visibility,ids:p.playlist_items.map(x=>x.track_id),trackData:p.playlist_items.map(x=>x.track)}]));for(const op of Object.values(cloud.pending(uid))){if(op.type==='like'){if(op.liked)likeMap.set(op.track.id,op.track);else likeMap.delete(op.track.id)}else if(op.type==='deletePlaylist')listMap.delete(op.id);else listMap.set(op.id,{id:op.id,title:op.name,cover:op.cover,visibility:op.visibility,ids:op.tracks.map(t=>t.id),trackData:op.tracks})}for(const t of likeMap.values())registerCloudTrack(t);for(const p of listMap.values())for(const t of p.trackData||[])registerCloudTrack(t);liked=new Set(likeMap.keys());playlists=[...listMap.values()].map(({trackData,...p})=>p);save('likes',[...liked]);save('playlists',playlists);save('library-owner',uid);rememberOnline();render();cloud.flush()}
async function receiveAccount(event={}){if(event.event==='PASSWORD_RECOVERY'){accountMode='password';accountPanel();return}const uid=cloud.user?.id||null;if(uid===accountUid)return;const previous=read('library-owner','guest');if(!deletedAccountIds.has(previous))save('library-cache-'+previous,cacheSnapshot());accountUid=uid;const epoch=++accountEpoch;$('#account-btn').textContent=uid?'账号':'登录';if(!uid){const guest=read('library-cache-guest',{likes:[],playlists:[],tracks:[]});for(const t of guest.tracks||[])registerCloudTrack(t);liked=new Set(guest.likes||[]);playlists=guest.playlists||[];save('likes',[...liked]);save('playlists',playlists);save('library-owner','guest');render();return}liked=new Set();playlists=[];render();try{await cloud.ensureProfile();if(epoch!==accountEpoch)return;$('#account-btn').textContent=cloud.profile.display_name;await hydrateLibrary()}catch(error){if(epoch===accountEpoch){toast('账号已登录，云端资料暂未加载。请稍后重试。');const cached=read('library-cache-'+uid,null);if(cached){for(const t of cached.tracks||[])registerCloudTrack(t);liked=new Set(cached.likes||[]);playlists=cached.playlists||[];save('library-owner',uid);render()}}}}
async function initAccount(){if(!cloud.configured)return;cloud.addEventListener('deleted',event=>{deletedAccountIds.add(event.detail.id);try{localStorage.removeItem('echo-library-cache-'+event.detail.id);localStorage.removeItem('echo-cloud-outbox-'+event.detail.id)}catch{}});cloud.addEventListener('session',event=>receiveAccount(event.detail));cloud.addEventListener('sync',event=>{const status=$('#account-sync');if(status)status.textContent=event.detail.error?'同步待重试':event.detail.pending?'正在同步':'已同步'});try{await cloud.init();await receiveAccount()}catch{toast('账号服务连接失败，本机功能仍可使用。')}}
function accountPanel(){
 if(!cloud.configured){openSheet('账号','<h2>登录</h2><p>账号服务尚未连接。收藏和歌单目前保存在此设备。</p><button class="primary-btn" id="continue-local">继续使用</button>');return}
 if(cloud.user&&accountMode!=='password'){const p=cloud.profile,handle=p?.handle||'',name=p?.display_name||'';openSheet('账号',`<h2>${esc(name||'账号')}</h2><p>${esc(cloud.user.email||'')}</p><form id="profile-form"><label class="form-field">昵称<input name="display_name" value="${esc(name)}" required maxlength="40" autocomplete="nickname"></label><label class="form-field">用户名<input name="handle" value="${esc(handle)}" required minlength="3" maxlength="24" pattern="[a-z0-9_]+" autocapitalize="none" autocomplete="username"></label><button class="primary-btn" type="submit">保存</button><p class="form-message" role="status"></p></form><div class="account-actions"><span id="account-sync">${cloud.lastSyncError?'同步待重试':Object.keys(cloud.pending()).length?'正在同步':'已同步'}</span><button class="text-button" id="retry-cloud-sync">重试同步</button><button class="text-button" id="import-device-library">合并本机收藏与歌单</button><button class="text-button" id="signout-account">退出登录</button><button class="text-button danger" id="delete-account-confirm">删除账号</button></div>`);return}
 const mode=accountMode,title={signin:'登录',signup:'注册',reset:'重设密码',password:'设置新密码'}[mode];openSheet('ECHO',`<h2>${title}</h2><form id="auth-form" data-mode="${mode}">${mode!=='password'?'<label class="form-field">邮箱<input name="email" type="email" required autocomplete="email"></label>':''}${mode!=='reset'?`<label class="form-field">密码<input name="password" type="password" required minlength="${mode==='signin'?1:12}" autocomplete="${mode==='signin'?'current-password':'new-password'}"></label>`:''}<button class="primary-btn" type="submit">${title}</button><p class="form-message" role="status"></p></form><div class="auth-links">${mode==='signin'?'<button class="text-button" data-auth-mode="signup">创建账号</button><button class="text-button" data-auth-mode="reset">忘记密码</button>':'<button class="text-button" data-auth-mode="signin">返回登录</button>'}</div>`)
}
async function importDeviceLibrary(){if(!cloud.user)return;const guest=read('library-cache-guest',null);if(!guest){toast('没有待合并的本机资料。');return}for(const t of guest.tracks||[])registerCloudTrack(t);for(const id of guest.likes||[]){liked.add(id);cloudLike(id,true)}for(const p of guest.playlists||[]){if(!playlists.some(x=>x.id===p.id))playlists.push(p);cloudPlaylist(p)}save('likes',[...liked]);save('playlists',playlists);render();toast('本机收藏和歌单已加入同步队列。')}
async function renderFriends(){const epoch=++friendEpoch;if(!cloud.user){main.innerHTML=`<div class="view-heading compact-heading"><h1>好友</h1></div>${empty('登录后添加好友','使用用户名查找好友。','<button class="primary-btn" id="account-btn-inline">登录</button>')}`;return}main.innerHTML='<div class="view-heading compact-heading"><h1>好友</h1><button class="secondary-btn" id="refresh-friends">刷新</button></div><form id="people-search" class="people-search"><label for="person-query">用户名</label><div><input id="person-query" name="handle" required minlength="3" maxlength="24" autocapitalize="none"><button class="primary-btn" type="submit">查找</button></div></form><div id="people-results"></div><div id="friend-list" role="status">正在加载…</div>';try{const list=await cloud.friends();if(epoch!==friendEpoch||view!=='friends')return;const incoming=list.filter(x=>x.status==='pending'&&x.addressee_id===cloud.user.id),sent=list.filter(x=>x.status==='pending'&&x.requester_id===cloud.user.id),friends=list.filter(x=>x.status==='accepted');const row=(r,type)=>`<div class="person-row"><span class="person-avatar">${esc((r.person?.display_name||'?').slice(0,1))}</span><div><strong>${esc(r.person?.display_name||'听友')}</strong><small>@${esc(r.person?.handle||'')}</small></div><span class="person-actions">${type==='incoming'?`<button class="secondary-btn" data-friend-accept="${r.id}">接受</button><button class="text-button" data-friend-remove="${r.id}">拒绝</button>`:type==='sent'?`<button class="text-button" data-friend-remove="${r.id}">取消申请</button>`:`<button class="text-button" data-friend-open="${r.person.id}">歌单</button><button class="text-button" data-friend-remove="${r.id}">移除</button>`}</span></div>`;$('#friend-list').innerHTML=`${incoming.length?`<div class="section-heading"><h2>好友申请</h2></div>${incoming.map(r=>row(r,'incoming')).join('')}`:''}<div class="section-heading"><h2>好友 · ${friends.length}</h2></div>${friends.length?friends.map(r=>row(r,'friend')).join(''):'<p class="muted-line">还没有好友。</p>'}${sent.length?`<div class="section-heading"><h2>已发送</h2></div>${sent.map(r=>row(r,'sent')).join('')}`:''}`}catch{$('#friend-list').innerHTML='<p>暂时无法加载好友，请重试。</p>'}}
async function showFriendPlaylists(id){openSheet('好友歌单','<h2>歌单</h2><p>正在加载…</p>');try{const data=await cloud.sharedPlaylists(id);for(const p of data){const entries=(p.playlist_items||[]).sort((a,b)=>a.position-b.position);entries.forEach(item=>registerCloudTrack(item.track));sharedCollections.set(p.id,{id:p.id,title:p.name,cover:p.cover||'assets/sea.jpg',ids:entries.map(t=>t.track_id)})}$('#sheet-content').innerHTML=`<h2>好友歌单</h2>${data.length?data.map(p=>`<button class="friend-playlist" data-collection="${esc(p.id)}">${icon('library')} ${esc(p.name)} ${icon('arrow')}</button>`).join(''):'<p>这位好友还没有分享歌单。</p>'}`}catch{$('#sheet-content').innerHTML='<h2>歌单</h2><p>暂时无法加载，请重试。</p>'}}
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;const d=target.dataset;try{if(d.authMode){accountMode=d.authMode;accountPanel()}if(target.id==='continue-local')sheet.close();if(target.id==='account-btn-inline')accountPanel();if(target.id==='signout-account'){await cloud.signOut();sheet.close()}if(target.id==='retry-cloud-sync'){await cloud.ensureProfile();await cloud.flush();await hydrateLibrary();toast(cloud.lastSyncError?'同步仍待重试。':'已同步')}if(target.id==='refresh-friends')renderFriends();if(d.friendRequest){target.disabled=true;await cloud.requestFriend(d.friendRequest);target.textContent='已申请'}if(d.friendAccept){await cloud.acceptFriend(d.friendAccept);renderFriends()}if(d.friendRemove){await cloud.removeFriend(d.friendRemove);renderFriends()}if(d.friendOpen)showFriendPlaylists(d.friendOpen);if(d.playlistPrivacy){if(!cloud.user){accountPanel();return}const p=playlists.find(p=>p.id===d.playlistPrivacy);p.visibility=p.visibility==='friends'?'private':'friends';save('playlists',playlists);cloudPlaylist(p);openCollection(p.id)}if(target.id==='delete-account-confirm')openSheet('删除账号','<h2>删除账号？</h2><p>账号、云端收藏、歌单和好友关系将被永久删除。本机音频文件不会删除。</p><button class="primary-btn danger" id="delete-account-final">确认删除账号</button>');if(target.id==='delete-account-final'){target.disabled=true;await cloud.deleteAccount();sheet.close();toast('账号资料已删除。')}}catch(error){target.disabled=false;toast(error.message||'操作失败，请重试。')}});
document.addEventListener('submit',async e=>{if(!['auth-form','profile-form','people-search'].includes(e.target.id))return;e.preventDefault();const form=e.target,button=$('button[type="submit"]',form),message=$('.form-message',form),data=new FormData(form);button.disabled=true;if(message)message.textContent='';try{if(form.id==='auth-form'){const mode=form.dataset.mode,email=String(data.get('email')||'').trim(),password=String(data.get('password')||'');if(mode==='signup'){const result=await cloud.signUp(email,password);if(message)message.textContent=result.session?'注册成功。':'请检查邮箱，点击确认链接后登录。'}else if(mode==='signin'){await cloud.signIn(email,password);sheet.close()}else if(mode==='reset'){await cloud.resetPassword(email);if(message)message.textContent='如果邮箱已注册，会收到重设密码的邮件。'}else{await cloud.updatePassword(password);accountMode='signin';sheet.close();toast('密码已更新。')}}else if(form.id==='profile-form'){await cloud.updateProfile(String(data.get('handle')).trim().toLowerCase(),String(data.get('display_name')));$('#account-btn').textContent=cloud.profile.display_name;if(message)message.textContent='已保存。'}else{const results=await cloud.searchPeople(String(data.get('handle')).trim());$('#people-results').innerHTML=results.length?results.map(p=>`<div class="person-row"><span class="person-avatar">${esc(p.display_name.slice(0,1))}</span><div><strong>${esc(p.display_name)}</strong><small>@${esc(p.handle)}</small></div><button class="secondary-btn" data-friend-request="${p.id}">添加</button></div>`).join(''):'<p class="muted-line">没有找到这个用户名。</p>'}}catch(error){if(message)message.textContent=error.message==='Invalid login credentials'?'邮箱或密码不正确。':error.code==='email_address_not_authorized'?'注册邮件服务尚未完成配置，暂时无法发送确认邮件。':error.code==='email_not_confirmed'?'请先确认邮箱后登录。':error.code==='over_email_send_rate_limit'?'邮件发送次数已达当前服务限制，请稍后重试。':error.message;else toast(error.message)}finally{if(button.isConnected)button.disabled=false}});
window.addEventListener('online',()=>cloud.flush());

const player=new EchoPlayerCore({audio,resolveTrack:getTrack,storage:window.localStorage,mediaSession:navigator.mediaSession||null,baseURL:location.href});
function syncPlayerState(state){current=state.currentId||current;queue=[...state.queue];shuffle=state.shuffle;repeat=state.repeat;save('current',current);save('queue',queue);save('shuffle',shuffle);save('repeat',repeat);save('volume',state.volume);updateVolumeControls(state.volume);updateControls();updatePlaybackStatus(state);}
function updatePlaybackStatus(state){const loading=['loading','buffering'].includes(state.status);$$('.toggle-play').forEach(button=>{button.classList.toggle('is-buffering',loading);button.setAttribute('aria-busy',String(loading));if(state.status==='error')button.setAttribute('aria-label','Retry playback')});const status=$('#playback-status');status.textContent=loading?'Buffering…':state.status==='error'?'Audio unavailable':state.status==='ended'?'Queue finished':'';status.hidden=!status.textContent;$('#retry-playback').hidden=state.status!=='error';}
player.addEventListener('statechange',event=>syncPlayerState(event.detail));
player.addEventListener('trackchange',()=>{syncPlayerState(player.getSnapshot());updatePlayer();refreshTrackRows()});
player.addEventListener('timeupdate',updateProgress);
player.addEventListener('error',event=>toast(event.detail.message));
window.addEventListener('pagehide',()=>player.persist());
document.addEventListener('visibilitychange',()=>{if(document.hidden){player.persist();if(audio.provider==='youtube')player.pause()}});
async function init(){applyPlatform();render();try{db=await openDatabase();const saved=await dbRequest('readonly',s=>s.getAll());for(const t of saved)tracks.push({...t,src:URL.createObjectURL(t.file)})}catch{toast('Device storage is unavailable. Included music still works.')}queue=queue.filter(id=>getTrack(id));if(!getTrack(current))current='sanctuary';liked=new Set([...liked].filter(id=>getTrack(id)));playlists.forEach(p=>p.ids=p.ids.filter(id=>getTrack(id)));player.restore({currentId:current,queue,shuffle,repeat,volume:Number(read('volume',.8))});render();updatePlayer();const shared=new URLSearchParams(location.hash.slice(1)).get('track');if(shared&&!getTrack(shared)&&/^youtube-[A-Za-z0-9_-]{11}$/.test(shared))tracks.push(youtubeTrack({videoId:shared.slice(8)}));if(shared&&!getTrack(shared)&&/^audius-[a-zA-Z0-9]+$/.test(shared)){try{const result=await catalogRequest('/tracks/'+shared.slice(7));if(streamable(result.data)){tracks.push(mapCatalogTrack(result.data));rememberOnline()}}catch{toast('This shared song is unavailable.')}}if(shared&&getTrack(shared)){player.select(shared,{autoplay:false});openNowPlaying()}if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});initAccount();}
init();
